        [1699] = {{["coords"]=shared[5099],["cost"]=shared[4810],["instructions"]="Learn Legion Enchanting and follow Enchanter Nalthanis's profession quests in Broken Isles Dalaran (38.3, 40.3) until An Enchanting Home. Visit Tigrid the Charmer in Stormheim (39.4, 42.6), complete A Touch of Magic, then Halls of Valor: Revenge of the Enchantress. Recover her rod in Halls of Valor and return it to unlock her shop. Buy Formula: Enchanted Cauldron for 50 Arkhana, learn it and craft the pet. Alternatively, buy the crafted pet or a caged copy from another player or the Auction House.",["kind"]="Professions",["locationType"]="Enchanting formula vendor",["maps"]=shared[1],["npcID"]=98367,["npcName"]="Tigrid the Charmer",["references"]={"https://www.wowhead.com/item=128621","https://www.wowhead.com/npc=98367/tigrid-the-charmer","https://www.wowhead.com/quest=39904","https://github.com/ATTWoWAddon/AllTheThings/blob/f8113a527789bf361e070d7cde94d1f57a22b2b8/db/Standard/Categories/Professions.lua"},["researched"]=true,["reviewedAt"]="2026-10-30",["sourceName"]="Legion Enchanting - Tigrid the Charmer's formula",["unlockQuestID"]=39904}},
        [1700] = {{["coords"]=shared[5099],["cost"]=shared[4810],["instructions"]="Learn Legion Enchanting and follow Enchanter Nalthanis's profession quests in Broken Isles Dalaran (38.3, 40.3) until An Enchanting Home. Visit Tigrid the Charmer in Stormheim (39.4, 42.6), complete A Touch of Magic, then Halls of Valor: Revenge of the Enchantress. Recover her rod in Halls of Valor and return it to unlock her shop. Buy Formula: Enchanted Torch for 50 Arkhana, learn it and craft the pet. Alternatively, buy the crafted pet or a caged copy from another player or the Auction House.",["kind"]="Professions",["locationType"]="Enchanting formula vendor",["maps"]=shared[1],["npcID"]=98367,["npcName"]="Tigrid the Charmer",["references"]={"https://www.wowhead.com/item=128622","https://www.wowhead.com/npc=98367/tigrid-the-charmer","https://www.wowhead.com/quest=39904","https://github.com/ATTWoWAddon/AllTheThings/blob/f8113a527789bf361e070d7cde94d1f57a22b2b8/db/Standard/Categories/Professions.lua"},["researched"]=true,["reviewedAt"]="2026-10-30",["sourceName"]="Legion Enchanting - Tigrid the Charmer's formula",["unlockQuestID"]=39904}},
        [1701] = {{["coords"]=shared[5099],["instructions"]="Learn Legion Enchanting and progress Enchanter Nalthanis's profession story in Broken Isles Dalaran (38.3, 40.3) until An Enchanting Home. Visit Tigrid the Charmer in Stormheim (39.4, 42.6), complete A Touch of Magic, and accept Halls of Valor: Revenge of the Enchantress. Recover Tigrid's Enchanting Rod in Halls of Valor and return it to her to learn Enchanted Pen. Craft the pet with the learned recipe, or buy a crafted/caged copy on the Auction House. The map follows the first unfinished prerequisite; the quest rewards the recipe, not the finished pet.",["kind"]="Professions",["locationType"]="Enchanting recipe quest",["maps"]=shared[1],["npcID"]=98367,["npcName"]="Tigrid the Charmer",["progressQuestID"]=39904,["references"]={"https://www.wowhead.com/quest=39904","https://www.wowhead.com/item=128535/enchanted-pen","https://github.com/ATTWoWAddon/AllTheThings/blob/f8113a527789bf361e070d7cde94d1f57a22b2b8/db/Standard/Categories/Professions.lua"},["researched"]=true,["reviewedAt"]="2026-10-30",["sourceName"]="Legion Enchanting - Halls of Valor: Revenge of the Enchantress"}},
