        [1756] = {{["coords"]=shared[5061],["instructions"]="Learn Legion Alchemy from Deucus Valdera in Broken Isles Dalaran (41.3, 33.4). Complete the alchemy-station quest chain through Return the Filter, then buy Recipe: Wild Transmutation from Patricia Egan in the same shop (42.2, 32.3). Perform Wild Transmutation at the Dalaran Alchemy Station each day until you discover Transmute: Meat to Pet. Use that recipe to make a Pulsating Sac and wait 7 real-time days for it to become a Growling Sac. Open it for a random pet; Ridgeback Piglet is one possible result. Repeat if needed, or buy a caged Ridgeback Piglet on the Auction House.",["kind"]="Professions",["locationType"]="Wild Transmutation recipe / Dalaran Alchemy Station",["maps"]=shared[1],["npcID"]=92457,["npcName"]="Patricia Egan",["references"]=shared[7346],["researched"]=true,["reviewedAt"]="2026-10-30",["sourceName"]="Legion Alchemy - Transmute: Meat to Pet / Growling Sac",["unlockQuestID"]=39338}},
        [1759] = {{["coords"]=shared[5061],["instructions"]="Learn Legion Alchemy from Deucus Valdera in Broken Isles Dalaran (41.3, 33.4). Complete the alchemy-station quest chain through Return the Filter, then buy Recipe: Wild Transmutation from Patricia Egan in the same shop (42.2, 32.3). Perform Wild Transmutation at the Dalaran Alchemy Station each day until you discover Transmute: Meat to Pet. Use that recipe to make a Pulsating Sac and wait 7 real-time days for it to become a Growling Sac. Open it for a random pet; Thaumaturgical Piglet is one possible result. Repeat if needed, or buy a caged Thaumaturgical Piglet on the Auction House.",["kind"]="Professions",["locationType"]="Wild Transmutation recipe / Dalaran Alchemy Station",["maps"]=shared[1],["npcID"]=92457,["npcName"]="Patricia Egan",["references"]=shared[7346],["researched"]=true,["reviewedAt"]="2026-10-30",["sourceName"]="Legion Alchemy - Transmute: Meat to Pet / Growling Sac",["unlockQuestID"]=39338}},
