        [28202] = {["coords"]=shared[4642],["description"]="This is a race-specific quest where different races get different versions of this quest. This particular version is only available for Humans, Dwarfs, Void Elves, Kul Tirans, and Dark Iron Dwarfs. Completing this quest might give completion credit to other versions of this quest, and vice versa.\n\n\nSolution for Human, Dwarf and Dark Iron Dwarf:\n2 Hides, 4 Handfuls of Mud, and 2 Spools of Thread.\n\nSolution for Void Elf:\n3 Hides, 2 Handfuls of Mud, and 1 Spool of Thread.\n\nSolution for Kul Tiran:\n4 Hides, 1 Handful of Mud, and 3 Spools of Thread.\n\n",["lvl"]=15,["maps"]=shared[31],["qgs"]=shared[617],["questID"]=28202,["races"]={1,3,29,32,34,85},["sourceQuests"]=shared[320]},
        [28203] = {["coords"]=shared[4642],["description"]="This is a race-specific quest where different races get different versions of this quest. This particular version is only available for Draenei, Worgen, Tushui Pandaren, Lightforged Draenei, and Alliance Dracthyr. Completing this quest might give completion credit to other versions of this quest, and vice versa.\n\n\nSolution:\n\n4 Hides\n1 Handful of Mud\n3 Spools of Thread",["lvl"]=15,["maps"]=shared[31],["qgs"]=shared[617],["questID"]=28203,["races"]={11,22,25,30,52},["sourceQuests"]=shared[320]},
